package org.sleepwell.app;
import android.os.SystemClock;import android.util.*;import android.view.*;import androidx.activity.ComponentActivity;import androidx.camera.core.*;import androidx.camera.core.resolutionselector.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.view.PreviewView;import androidx.camera.mlkit.vision.MlKitAnalyzer;import androidx.core.content.ContextCompat;import androidx.lifecycle.Lifecycle;import com.google.common.util.concurrent.ListenableFuture;import com.google.mlkit.vision.pose.*;import com.google.mlkit.vision.pose.defaults.PoseDetectorOptions;import java.util.*;import java.util.concurrent.*;
/** Visible front-camera analysis through CameraX MlKitAnalyzer. Only numeric observations leave it. */
final class PoseCamera implements AutoCloseable,CameraTaskPorts.Capture {
 interface Port extends CameraTaskPorts.Capture{void start(Listener listener);}
 interface Factory{Port create(ComponentActivity activity);}
 static Factory factory=RealPort::new;
 private static final class RealPort implements Port{final PoseCamera camera;RealPort(ComponentActivity activity){camera=new PoseCamera(activity);}public View preview(){return camera.preview();}public void start(Listener listener){camera.start(listener);}public void close(){camera.close();}public boolean released(){return camera.released();}}
 interface Listener{void frame(PoseHold.Sample sample,String issue);void error(String issue);}
 static final class Meta{final int width,height;final long at;Meta(int w,int h,long at){width=w;height=h;this.at=at;}}
 final ComponentActivity activity;final PreviewView view;final Map<Long,Meta> frames=new ConcurrentHashMap<>();ProcessCameraProvider provider;Preview preview;ImageAnalysis analysis;Camera camera;PoseDetector detector;ExecutorService worker;CameraCaptureCleanup cleanup;volatile boolean active;volatile long generation;
 PoseCamera(ComponentActivity a){activity=a;view=new PreviewView(a);view.setImplementationMode(PreviewView.ImplementationMode.COMPATIBLE);view.setScaleType(PreviewView.ScaleType.FIT_CENTER);}
 public View preview(){return view;}
 public void start(Listener listener){close();if(!released())throw new IllegalStateException("Previous camera cleanup is pending. Retry cleanup.");if(!CameraCaptureLease.acquire(this))throw new IllegalStateException("Another camera owner is active or still releasing. Retry later.");long ticket=++generation;active=true;worker=CameraCaptureLease.worker(this);cleanup=new CameraCaptureCleanup(this,worker,this::closeMain,()->{if(detector!=null){detector.close();detector=null;}});detector=PoseDetection.getClient(new PoseDetectorOptions.Builder().setDetectorMode(PoseDetectorOptions.STREAM_MODE).build());PoseDetector owned=detector;ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(activity);future.addListener(()->{if(!live(ticket)||!activity.getLifecycle().getCurrentState().isAtLeast(Lifecycle.State.RESUMED))return;try{if(PoseCameraAccess.status(activity)!=PoseCameraAccess.Status.READY)throw new SecurityException();provider=future.get();if(!provider.hasCamera(CameraSelector.DEFAULT_FRONT_CAMERA))throw new IllegalStateException();preview=new Preview.Builder().build();preview.setSurfaceProvider(view.getSurfaceProvider());analysis=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).setResolutionSelector(new ResolutionSelector.Builder().setAspectRatioStrategy(AspectRatioStrategy.RATIO_4_3_FALLBACK_AUTO_STRATEGY).setResolutionStrategy(new ResolutionStrategy(new Size(640,480),ResolutionStrategy.FALLBACK_RULE_CLOSEST_LOWER_THEN_HIGHER)).build()).build();MlKitAnalyzer analyzer=new MlKitAnalyzer(List.of(owned),ImageAnalysis.COORDINATE_SYSTEM_ORIGINAL,ContextCompat.getMainExecutor(activity),result->{Meta meta=frames.remove(result.getTimestamp());if(!live(ticket)||meta==null)return;if(result.getThrowable(owned)!=null){listener.frame(null,"Pose detector unavailable. Retry or use Math.");return;}Pose pose=result.getValue(owned);if(pose==null||pose.getAllPoseLandmarks().isEmpty()){listener.frame(null,"Step back so your head, hands and hips are visible.");return;}int[] types={PoseLandmark.NOSE,PoseLandmark.LEFT_SHOULDER,PoseLandmark.RIGHT_SHOULDER,PoseLandmark.LEFT_ELBOW,PoseLandmark.RIGHT_ELBOW,PoseLandmark.LEFT_WRIST,PoseLandmark.RIGHT_WRIST,PoseLandmark.LEFT_HIP,PoseLandmark.RIGHT_HIP};double[] x=new double[9],y=new double[9],confidence=new double[9];for(int n=0;n<types.length;n++){PoseLandmark landmark=pose.getPoseLandmark(types[n]);if(landmark==null){listener.frame(null,"Keep your upper body and both hands in view.");return;}x[n]=landmark.getPosition().x/meta.width;y[n]=landmark.getPosition().y/meta.height;confidence[n]=landmark.getInFrameLikelihood();}PoseHold.Sample sample=new PoseHold.Sample(x,y,confidence,meta.at);listener.frame(sample,!sample.framed()?"Face the camera with your head, arms and hips in good light.":!sample.raised()?"Raise both hands above your head, then hold steady.":"");});long[] last={-1,-1};analysis.setAnalyzer(worker,raw->{ImageProxy image=cleanup.track(raw);boolean delegated=false;try{if(!live(ticket))return;long now=SystemClock.elapsedRealtime(),sensor=image.getImageInfo().getTimestamp();if(last[0]>=0&&now-last[0]<200||sensor<=last[1])return;last[0]=now;last[1]=sensor;long captured=PictureHold.captured(sensor,now,System.nanoTime()/1000000L);if(captured<0){activity.runOnUiThread(()->{if(live(ticket))listener.frame(null,"Camera timing is unavailable. Retry or use Math.");});return;}int rotation=image.getImageInfo().getRotationDegrees();int w=rotation==90||rotation==270?image.getHeight():image.getWidth(),h=rotation==90||rotation==270?image.getWidth():image.getHeight();if(w<360||h<360)throw new IllegalArgumentException();if(frames.size()>3)frames.clear();frames.put(sensor,new Meta(w,h,captured));analyzer.analyze(image);delegated=true;}catch(RuntimeException unavailable){activity.runOnUiThread(()->{if(live(ticket))listener.frame(null,"This camera frame could not be analyzed. Retry or use Math.");});}finally{if(!delegated)image.close();}});int rotation=view.getDisplay()==null?Surface.ROTATION_0:view.getDisplay().getRotation();UseCaseGroup group=new UseCaseGroup.Builder().setViewPort(new ViewPort.Builder(new Rational(4,3),rotation).setScaleType(ViewPort.FIT).build()).addUseCase(preview).addUseCase(analysis).build();camera=provider.bindToLifecycle(activity,CameraSelector.DEFAULT_FRONT_CAMERA,group);camera.getCameraInfo().getCameraState().observe(activity,state->{if(live(ticket)&&state.getError()!=null)listener.error("Front camera is unavailable or in use. Retry or use Math.");});}catch(Exception unavailable){if(live(ticket))listener.error(unavailable instanceof SecurityException?"Camera access is off.":"The front camera or pose detector could not start. Use Math or retry.");}},ContextCompat.getMainExecutor(activity));}
 boolean live(long ticket){return active&&generation==ticket&&!activity.isDestroyed();}
 public boolean released(){return cleanup==null||cleanup.released();}
 public void close(){active=false;generation++;frames.clear();if(cleanup!=null)cleanup.close();}
 private void closeMain(){
 if(analysis!=null)analysis.clearAnalyzer();
 if(camera!=null)camera.getCameraInfo().getCameraState().removeObservers(activity);
 if(provider!=null){if(preview!=null&&analysis!=null)provider.unbind(preview,analysis);else if(preview!=null)provider.unbind(preview);else if(analysis!=null)provider.unbind(analysis);}
 preview=null;analysis=null;camera=null;
}
}
